import{_ as n,I as a,o as s,c as d,b6 as i,j as l,J as o,w as c}from"./chunks/framework.BUXTSoD9.js";const k=JSON.parse('{"title":"Desarrollo Practico: Sistema de Recomendacion de Peliculas con Spring Boot","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/stage-2/assignments/movie-recommendation-springboot/index.md","filePath":"es-es/stage-2/assignments/movie-recommendation-springboot/index.md"}'),p={name:"es-es/stage-2/assignments/movie-recommendation-springboot/index.md"},u={style:{margin:"32px 0"}};function m(g,e,h,b,f,v){const t=a("StepBar"),r=a("ClientOnly");return s(),d("div",null,[e[0]||(e[0]=i('<h1 id="desarrollo-practico-sistema-de-recomendacion-de-peliculas-con-spring-boot" tabindex="-1">Desarrollo Practico: Sistema de Recomendacion de Peliculas con Spring Boot <a class="header-anchor" href="#desarrollo-practico-sistema-de-recomendacion-de-peliculas-con-spring-boot" aria-label="Permalink to “Desarrollo Practico: Sistema de Recomendacion de Peliculas con Spring Boot”">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripcion general <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to “Descripcion general”">​</a></h2><p>Este proyecto practico te requiere trabajar con un PRD real para completar un sitio web de peliculas con capacidades de recomendacion usando Spring Boot. El desafio central de este proyecto radica en que no es un simple CRUD, sino que necesitas reflexionar sobre como el comportamiento del usuario afecta los resultados de recomendacion y como hacer que las recomendaciones sean explicables.</p><p>Esta es la seccion de practica integral de la Etapa 2. Por primera vez te enfrentarás al desarrollo de un producto de tipo &quot;contenido + comportamiento + recomendacion&quot;, un patron muy comun en comercio electronico, plataformas de contenido y feeds personalizados.</p><h2 id="conocimientos-previos" tabindex="-1">Conocimientos previos <a class="header-anchor" href="#conocimientos-previos" aria-label="Permalink to “Conocimientos previos”">​</a></h2><p>Antes de comenzar este proyecto, ya deberias dominar lo siguiente:</p><ul><li>Diseno de paginas frontend y uso de bibliotecas de componentes (<a href="./../../frontend/ui-design/">Diseno UI</a>, <a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a>)</li><li>Diseno y desarrollo de interfaces backend (<a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a>)</li><li>Fundamentos de bases de datos y Supabase (<a href="./../../backend/database-supabase/">De la base de datos a Supabase</a>)</li><li>Flujo de trabajo de Git y despliegue (<a href="./../../backend/git-workflow/">Git y GitHub</a>, <a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a>)</li></ul><h2 id="objetivos-de-aprendizaje" tabindex="-1">Objetivos de aprendizaje <a class="header-anchor" href="#objetivos-de-aprendizaje" aria-label="Permalink to “Objetivos de aprendizaje”">​</a></h2><p>Despues de completar esta practica, podras:</p><ol><li>Leer un PRD y extraer la lista de tareas de desarrollo para un sistema de recomendacion</li><li>Usar Spring Boot para construir un proyecto backend e implementar API RESTful</li><li>Disenar el flujo de datos completo de &quot;comportamiento del usuario a recomendacion&quot;</li><li>Implementar logica de recomendacion explicable</li><li>Completar la integracion de extremo a extremo, entregando un prototipo de producto demostrable</li></ol><h2 id="introduccion-del-proyecto" tabindex="-1">Introduccion del proyecto <a class="header-anchor" href="#introduccion-del-proyecto" aria-label="Permalink to “Introduccion del proyecto”">​</a></h2><p>El producto que vas a construir es un sitio web de peliculas con capacidades de recomendacion:</p><table tabindex="0"><thead><tr><th>Funcionalidad</th><th>Descripcion</th></tr></thead><tbody><tr><td><strong>Navegacion y busqueda</strong></td><td>Los usuarios pueden navegar y buscar peliculas</td></tr><tr><td><strong>Calificacion y favoritos</strong></td><td>Los usuarios pueden calificar peliculas y agregarlas a favoritos</td></tr><tr><td><strong>Recomendacion personalizada</strong></td><td>El sistema genera resultados de recomendacion basados en el comportamiento del usuario</td></tr><tr><td><strong>Panel de administracion</strong></td><td>Los administradores mantienen los datos de peliculas y revisan la efectividad de las recomendaciones</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>El documento de requisitos de este proyecto esta en GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/es-es/stage-2/assignments/movie-recommendation-springboot/PRD.md" target="_blank" rel="noreferrer">Ver PRD</a></p></div>',14)),l("div",u,[o(r,null,{default:c(()=>[o(t,{active:0,items:[{title:"Analisis de requisitos",description:"Leer el PRD, definir la estrategia de recomendacion, datos de comportamiento y alcance del panel"},{title:"Construccion del esqueleto",description:"Usar IA para generar las paginas de lista, detalle, recomendacion y panel de administracion"},{title:"Desarrollo iterativo",description:"Agregar logica de recomendacion, registro de comportamiento y panel de administracion"},{title:"Integracion y despliegue",description:"Verificar de extremo a extremo, desplegar y preparar la demostracion"}]})]),_:1})]),e[1]||(e[1]=i(`<h2 id="primera-parte-analisis-de-requisitos" tabindex="-1">Primera parte: Analisis de requisitos <a class="header-anchor" href="#primera-parte-analisis-de-requisitos" aria-label="Permalink to “Primera parte: Analisis de requisitos”">​</a></h2><h3 id="_1-1-leer-el-prd" tabindex="-1">1.1 Leer el PRD <a class="header-anchor" href="#_1-1-leer-el-prd" aria-label="Permalink to “1.1 Leer el PRD”">​</a></h3><p>Abre el documento PRD y responde las siguientes preguntas clave:</p><ul><li>Cual es la estrategia de recomendacion? La primera version debe usar una version explicable (como similitud de calificaciones)?</li><li>Que datos de comportamiento del usuario deben almacenarse? (calificaciones, favoritos, historial de navegacion, etc.)</li><li>Que metricas de efectividad de recomendacion necesita ver el administrador?</li><li>La lista de paginas esta completa?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si no tienes respuestas claras a las preguntas anteriores, no comiences a escribir codigo. La comprension inadecuada de los requisitos es la causa mas comun de retrabajo.</p></div><h3 id="_1-2-confirmar-la-arquitectura-del-sistema" tabindex="-1">1.2 Confirmar la arquitectura del sistema <a class="header-anchor" href="#_1-2-confirmar-la-arquitectura-del-sistema" aria-label="Permalink to “1.2 Confirmar la arquitectura del sistema”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;Paginas frontend&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; auth[&quot;Autenticacion de usuario&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; movie[&quot;Lista / Detalle de peliculas&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; behavior[&quot;Calificacion / Favoritos&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  behavior --&gt; reco[&quot;Logica de recomendacion&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  reco --&gt; db[&quot;Base de datos&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin[&quot;Panel de administracion&quot;] --&gt; db</span></span></code></pre></div><h2 id="segunda-parte-construccion-del-esqueleto-del-proyecto" tabindex="-1">Segunda parte: Construccion del esqueleto del proyecto <a class="header-anchor" href="#segunda-parte-construccion-del-esqueleto-del-proyecto" aria-label="Permalink to “Segunda parte: Construccion del esqueleto del proyecto”">​</a></h2><h3 id="_2-1-generar-paginas-frontend" tabindex="-1">2.1 Generar paginas frontend <a class="header-anchor" href="#_2-1-generar-paginas-frontend" aria-label="Permalink to “2.1 Generar paginas frontend”">​</a></h3><p>Referencia de prompts:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Basandote en el PRD actual, ayudame a generar el esqueleto frontend de un sistema de recomendacion de peliculas con Spring Boot.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requisitos:</span></span>
<span class="line"><span>1. Paginas incluidas: inicio, lista de peliculas, detalle de pelicula, pagina de recomendacion, centro personal, panel de administracion</span></span>
<span class="line"><span>2. Primero generar solo la estructura de paginas y datos ficticios, sin conectar interfaces reales</span></span>
<span class="line"><span>3. El estilo debe parecerse a un producto de contenido real, no a un demo de clase</span></span></code></pre></div><h3 id="_2-2-verificar-la-estructura-de-paginas" tabindex="-1">2.2 Verificar la estructura de paginas <a class="header-anchor" href="#_2-2-verificar-la-estructura-de-paginas" aria-label="Permalink to “2.2 Verificar la estructura de paginas”">​</a></h3><p>Verificar item por item:</p><ul><li>[ ] La pagina de lista de peliculas soporta busqueda y filtrado</li><li>[ ] La pagina de detalle de pelicula incluye botones de calificacion y favoritos</li><li>[ ] La pagina de recomendacion puede mostrar resultados y razones de recomendacion</li><li>[ ] El panel de administracion puede mostrar datos de peliculas y efectividad de recomendacion</li></ul><h2 id="tercera-parte-desarrollo-iterativo" tabindex="-1">Tercera parte: Desarrollo iterativo <a class="header-anchor" href="#tercera-parte-desarrollo-iterativo" aria-label="Permalink to “Tercera parte: Desarrollo iterativo”">​</a></h2><h3 id="_3-1-avanzar-por-modulos" tabindex="-1">3.1 Avanzar por modulos <a class="header-anchor" href="#_3-1-avanzar-por-modulos" aria-label="Permalink to “3.1 Avanzar por modulos”">​</a></h3><ol><li><strong>Configuracion del proyecto Spring Boot</strong>: Estructura del proyecto, configuracion de base de datos, CRUD basico</li><li><strong>Gestion de datos de peliculas</strong>: Lista de peliculas, detalle, interfaz de busqueda</li><li><strong>Comportamiento del usuario</strong>: Interfaces de calificacion y favoritos, escritura de datos de comportamiento</li><li><strong>Logica de recomendacion</strong>: Implementacion del algoritmo de recomendacion basado en comportamiento del usuario</li><li><strong>Visualizacion de recomendaciones</strong>: Mostrar resultados de recomendacion incluyendo las razones</li><li><strong>Panel de administracion</strong>: Mantenimiento de datos de peliculas, revision de efectividad de recomendacion</li></ol><h3 id="_3-2-autoverificacion-de-modulos" tabindex="-1">3.2 Autoverificacion de modulos <a class="header-anchor" href="#_3-2-autoverificacion-de-modulos" aria-label="Permalink to “3.2 Autoverificacion de modulos”">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificacion</th><th>Metodo de verificacion</th></tr></thead><tbody><tr><td>Funcionalidad basica</td><td>Lista, detalle, calificacion, favoritos forman un ciclo completo</td></tr><tr><td>Vinculacion de recomendacion</td><td>El comportamiento del usuario afecta los resultados de recomendacion</td></tr><tr><td>Explicabilidad de recomendacion</td><td>El usuario puede entender por que se le recomiendan estas peliculas</td></tr><tr><td>Datos del panel</td><td>El administrador puede ver datos de peliculas y efectividad de recomendacion</td></tr></tbody></table><h2 id="cuarta-parte-integracion-y-despliegue" tabindex="-1">Cuarta parte: Integracion y despliegue <a class="header-anchor" href="#cuarta-parte-integracion-y-despliegue" aria-label="Permalink to “Cuarta parte: Integracion y despliegue”">​</a></h2><h3 id="_4-1-pruebas-de-extremo-a-extremo" tabindex="-1">4.1 Pruebas de extremo a extremo <a class="header-anchor" href="#_4-1-pruebas-de-extremo-a-extremo" aria-label="Permalink to “4.1 Pruebas de extremo a extremo”">​</a></h3><p>Verificar al menos los siguientes escenarios:</p><ul><li>Navegar peliculas -&gt; Calificar -&gt; Agregar a favoritos -&gt; Ver pagina de recomendacion, confirmar que los resultados de recomendacion cambian</li><li>Iniciar sesion como administrador -&gt; Agregar peliculas -&gt; Ver estadisticas de efectividad de recomendacion</li></ul><h2 id="entregables" tabindex="-1">Entregables <a class="header-anchor" href="#entregables" aria-label="Permalink to “Entregables”">​</a></h2><p>Despues de completar este proyecto, necesitas enviar lo siguiente:</p><ul><li>[ ] Enlace de demostracion en linea accesible</li><li>[ ] Enlace al repositorio de codigo fuente (incluyendo README)</li><li>[ ] Documento PRD</li><li>[ ] Capturas de pantalla de paginas clave (lista de peliculas, detalle de pelicula, pagina de recomendacion, panel de administracion)</li><li>[ ] Video de demostracion de 60 segundos</li></ul><h2 id="criterios-de-evaluacion" tabindex="-1">Criterios de evaluacion <a class="header-anchor" href="#criterios-de-evaluacion" aria-label="Permalink to “Criterios de evaluacion”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Requisitos basicos</th><th>Requisitos avanzados</th></tr></thead><tbody><tr><td>Alineacion con PRD</td><td>Paginas, funcionalidades y estructura de datos basicamente cumplen con el PRD</td><td>Puede explicar claramente las decisiones de diseno</td></tr><tr><td>Ciclo completo del producto</td><td>Navegar -&gt; Calificar -&gt; Agregar a favoritos -&gt; Recomendar funciona completamente</td><td>El comportamiento de calificacion afecta significativamente los resultados de recomendacion</td></tr><tr><td>Calidad de recomendacion</td><td>Resultados de recomendacion razonables, razones de recomendacion explicables</td><td>Soporta multiples estrategias de recomendacion</td></tr><tr><td>Capacidades del panel</td><td>Datos de peliculas y efectividad de recomendacion visibles</td><td>Tiene metricas estadisticas como precision de recomendacion</td></tr><tr><td>Completitud de ingenieria</td><td>Frontend, backend Spring Boot y base de datos conectados</td><td>Las interfaces de recomendacion tienen cache u optimizacion de rendimiento</td></tr></tbody></table><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to “Referencias”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Diseno UI</a></li><li><a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a></li><li><a href="./../../backend/database-supabase/">De la base de datos a Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a></li><li><a href="./../../backend/git-workflow/">Flujo de trabajo de Git y GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a></li></ul>`,30))])}const E=n(p,[["render",m]]);export{k as __pageData,E as default};
